-- Commerce organ, P4 money states -- generated by noctusai_lib.domain.commerce.money_sql (do not hand-edit)

SET search_path = commerce, public;

-- Orders: the regenerate-payment claim columns (a pre-P4 order with a charge counts as attempt 1).
ALTER TABLE commerce.commerce_orders ADD COLUMN IF NOT EXISTS charge_attempts INTEGER NOT NULL DEFAULT 0 CHECK (charge_attempts >= 0);
ALTER TABLE commerce.commerce_orders ADD COLUMN IF NOT EXISTS last_charge_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now();
UPDATE commerce.commerce_orders SET charge_attempts = 1 WHERE gateway_charge_id IS NOT NULL AND charge_attempts = 0;

-- Store profile: card installments (D33). interest_monthly_bps NULL = follow the platform default (D41).
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS installments_max INTEGER NOT NULL DEFAULT 12
    CHECK (installments_max BETWEEN 1 AND 12);
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS installments_interest_free INTEGER NOT NULL DEFAULT 3
    CHECK (installments_interest_free >= 1 AND installments_interest_free <= installments_max);
ALTER TABLE commerce.commerce_store_profiles ADD COLUMN IF NOT EXISTS installment_interest_monthly_bps INTEGER
    CHECK (installment_interest_monthly_bps IS NULL OR installment_interest_monthly_bps BETWEEN 0 AND 2000);

-- Order statuses grow by two (P4): replace the CHECKs (drop-then-add is idempotent).
ALTER TABLE commerce.commerce_orders DROP CONSTRAINT IF EXISTS commerce_orders_status_check;
ALTER TABLE commerce.commerce_orders ADD CONSTRAINT commerce_orders_status_check CHECK (status IN ('created', 'pending_payment', 'paid', 'expired', 'failed', 'cancelled', 'refunded', 'chargeback', 'partially_refunded', 'disputed'));
ALTER TABLE commerce.commerce_order_events DROP CONSTRAINT IF EXISTS commerce_order_events_from_status_check;
ALTER TABLE commerce.commerce_order_events ADD CONSTRAINT commerce_order_events_from_status_check CHECK (from_status IS NULL OR from_status IN ('created', 'pending_payment', 'paid', 'expired', 'failed', 'cancelled', 'refunded', 'chargeback', 'partially_refunded', 'disputed'));
ALTER TABLE commerce.commerce_order_events DROP CONSTRAINT IF EXISTS commerce_order_events_to_status_check;
ALTER TABLE commerce.commerce_order_events ADD CONSTRAINT commerce_order_events_to_status_check CHECK (to_status IN ('created', 'pending_payment', 'paid', 'expired', 'failed', 'cancelled', 'refunded', 'chargeback', 'partially_refunded', 'disputed'));

-- Order charges: one row per charge attempt (the buyer can regenerate a payment). `amount_cents` is what was charged INCLUDING buyer interest; commerce_orders.gateway_charge_id points at the CURRENT attempt.
CREATE TABLE IF NOT EXISTS commerce.commerce_order_charges (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id             UUID NOT NULL,
    order_id           UUID NOT NULL REFERENCES commerce.commerce_orders(id) ON DELETE CASCADE,
    attempt            INTEGER NOT NULL CHECK (attempt >= 1),
    gateway            TEXT NOT NULL,
    gateway_charge_id  TEXT NOT NULL,
    payment_method     TEXT NOT NULL CHECK (payment_method IN ('pix', 'boleto', 'credit_card')),
    installment_count  INTEGER NOT NULL DEFAULT 1 CHECK (installment_count BETWEEN 1 AND 12),
    amount_cents       BIGINT NOT NULL CHECK (amount_cents > 0),
    status             TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'expired', 'cancelled', 'failed')),
    checkout_url       TEXT,
    pix_qr             JSONB,
    due_at             TIMESTAMPTZ,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    closed_at          TIMESTAMPTZ
);
-- The gateway PARCELAMENTO id of a card order paid in installments (the refund target). NULL = not known yet:
-- resolved lazily from the gateway on first refund and persisted.
ALTER TABLE commerce.commerce_order_charges ADD COLUMN IF NOT EXISTS gateway_installment_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_commerce_order_charges_attempt ON commerce.commerce_order_charges (order_id, attempt);
CREATE UNIQUE INDEX IF NOT EXISTS uq_commerce_order_charges_gateway ON commerce.commerce_order_charges (org_id, gateway, gateway_charge_id);
CREATE INDEX IF NOT EXISTS idx_commerce_order_charges_org ON commerce.commerce_order_charges (org_id, order_id);
ALTER TABLE commerce.commerce_order_charges ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_order_charges_select_own_org" ON commerce.commerce_order_charges;
CREATE POLICY "commerce_order_charges_select_own_org" ON commerce.commerce_order_charges FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_order_charges;
CREATE POLICY "service_role_bypass" ON commerce.commerce_order_charges FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Refunds: requested -> done | failed. requested_by NULL = made in the gateway panel (reason 'gateway'). At most ONE requested refund per order (the DB backstop of the RPC's check); gateway_refund_id is nullable because Asaas refunds carry no id (W2).
CREATE TABLE IF NOT EXISTS commerce.commerce_refunds (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id             UUID NOT NULL,
    order_id           UUID NOT NULL REFERENCES commerce.commerce_orders(id) ON DELETE RESTRICT,
    charge_id          UUID NOT NULL REFERENCES commerce.commerce_order_charges(id) ON DELETE RESTRICT,
    amount_cents       BIGINT NOT NULL CHECK (amount_cents > 0),
    reason             TEXT NOT NULL DEFAULT '',
    status             TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'done', 'failed')),
    gateway_refund_id  TEXT,
    idempotency_key    TEXT,
    requested_by       UUID,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    done_at            TIMESTAMPTZ,
    CHECK (status <> 'done' OR done_at IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_commerce_refunds_gateway_id ON commerce.commerce_refunds (org_id, gateway_refund_id)
    WHERE gateway_refund_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_commerce_refunds_idempotency ON commerce.commerce_refunds (order_id, idempotency_key)
    WHERE idempotency_key IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_commerce_refunds_one_requested ON commerce.commerce_refunds (order_id)
    WHERE status = 'requested';
CREATE INDEX IF NOT EXISTS idx_commerce_refunds_order ON commerce.commerce_refunds (order_id, created_at);
CREATE INDEX IF NOT EXISTS idx_commerce_refunds_org ON commerce.commerce_refunds (org_id);
ALTER TABLE commerce.commerce_refunds ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_refunds_select_own_org" ON commerce.commerce_refunds;
CREATE POLICY "commerce_refunds_select_own_org" ON commerce.commerce_refunds FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_refunds;
CREATE POLICY "service_role_bypass" ON commerce.commerce_refunds FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Payment-recovery reminders sent per order (PK = the idempotency of the reminder job).
CREATE TABLE IF NOT EXISTS commerce.commerce_order_reminders (
    order_id  UUID NOT NULL REFERENCES commerce.commerce_orders(id) ON DELETE CASCADE,
    kind      TEXT NOT NULL CHECK (kind IN ('before_expiry', 'after_expiry')),
    org_id    UUID NOT NULL,
    sent_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (order_id, kind)
);
CREATE INDEX IF NOT EXISTS idx_commerce_order_reminders_org ON commerce.commerce_order_reminders (org_id);
ALTER TABLE commerce.commerce_order_reminders ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "commerce_order_reminders_select_own_org" ON commerce.commerce_order_reminders;
CREATE POLICY "commerce_order_reminders_select_own_org" ON commerce.commerce_order_reminders FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.commerce_order_reminders;
CREATE POLICY "service_role_bypass" ON commerce.commerce_order_reminders FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Refund creation under a row lock (CONTRACT §2.4 / D32). The order row is locked FOR UPDATE, so two
-- concurrent refunds serialize: the second sees the first's `requested` row and is refused.
CREATE OR REPLACE FUNCTION commerce.commerce_create_refund(
    p_org_id          UUID,
    p_order_id        UUID,
    p_amount_cents    BIGINT,
    p_reason          TEXT,
    p_requested_by    UUID,
    p_idempotency_key TEXT
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_order      commerce.commerce_orders%ROWTYPE;
    v_charge     commerce.commerce_order_charges%ROWTYPE;
    v_prior      commerce.commerce_refunds%ROWTYPE;
    v_row        commerce.commerce_refunds%ROWTYPE;
    v_refunded   BIGINT;
    v_remaining  BIGINT;
    v_amount     BIGINT;
BEGIN
    SELECT * INTO v_order FROM commerce.commerce_orders WHERE id = p_order_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'pedido_nao_encontrado');
    END IF;

    IF p_idempotency_key IS NOT NULL THEN
        SELECT * INTO v_prior FROM commerce.commerce_refunds WHERE order_id = p_order_id AND idempotency_key = p_idempotency_key;
        IF FOUND THEN
            RETURN jsonb_build_object('status', 'replayed', 'refund', to_jsonb(v_prior));
        END IF;
    END IF;

    IF v_order.status NOT IN ('paid', 'partially_refunded') THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'pedido_nao_reembolsavel');
    END IF;

    SELECT * INTO v_charge FROM commerce.commerce_order_charges
        WHERE order_id = p_order_id AND status = 'paid' ORDER BY attempt DESC LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'cobranca_nao_encontrada');
    END IF;

    IF EXISTS (SELECT 1 FROM commerce.commerce_refunds WHERE order_id = p_order_id AND status = 'requested') THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'estorno_em_andamento');
    END IF;

    SELECT COALESCE(SUM(amount_cents), 0) INTO v_refunded
        FROM commerce.commerce_refunds WHERE order_id = p_order_id AND status <> 'failed';
    v_remaining := v_charge.amount_cents - v_refunded;
    v_amount := COALESCE(p_amount_cents, v_remaining);
    IF v_amount <= 0 OR v_amount > v_remaining THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'valor_excede_saldo', 'refundable_cents', v_remaining);
    END IF;

    INSERT INTO commerce.commerce_refunds (org_id, order_id, charge_id, amount_cents, reason, status, idempotency_key, requested_by)
        VALUES (p_org_id, p_order_id, v_charge.id, v_amount, COALESCE(p_reason, ''), 'requested', p_idempotency_key, p_requested_by)
        RETURNING * INTO v_row;

    RETURN jsonb_build_object(
        'status', 'created',
        'refund', to_jsonb(v_row),
        'charge', jsonb_build_object(
            'id', v_charge.id,
            'gateway', v_charge.gateway,
            'gateway_charge_id', v_charge.gateway_charge_id,
            'amount_cents', v_charge.amount_cents,
            'installment_count', v_charge.installment_count,
            'gateway_installment_id', v_charge.gateway_installment_id
        ),
        'refundable_cents', v_remaining
    );
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.commerce_create_refund(UUID, UUID, BIGINT, TEXT, UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.commerce_create_refund(UUID, UUID, BIGINT, TEXT, UUID, TEXT) TO service_role;
